const LOCALES = ['fi', 'en', 'sv', 'es', 'et']

export const MESSAGES = Object.fromEntries(LOCALES.map((id) => [id, {}]))

ROWS.forEach((row) => {
  const [key, ...values] = row
  if (values.length !== LOCALES.length) throw new Error(`Message ${key} has ${values.length} translations`)
  LOCALES.forEach((id, index) => {
    MESSAGES[id][key] = values[index]
  })
})

export const MESSAGE_KEYS = ROWS.map((row) => row[0])
